      hu: ["A Gobir Királyság hagyományos fővárosa kb. 1835 óta", "A Sarkin Gobir (hagyományos uralkodó) rezidenciája", "A gobirava kultúra és a hausza nyelv központja", "A termékeny Maradi régióban, a Goulbi n'Maradi folyónál fekszik", "A hagyományos birkózóversenyek egyik fontos helyszíne", "Lakossága körülbelül 50 000 fő"],
      ro: ["Capitala tradițională a regatului Gobir din aproximativ 1835", "Reședința lui Sarkin Gobir (conducător tradițional)", "Centru al culturii Gobirawa și al limbii Hausa", "Situat în regiunea fertilă Maradi, pe râul Goulbi n'Maradi", "Loc important pentru competițiile tradiționale de lupte", "Populație de aproximativ 50.000 de locuitori"],
      en: ["Traditional capital of the Gobir Kingdom since approx. 1835", "Residence of the Sarkin Gobir (traditional ruler)", "Center of Gobirawa culture and Hausa language", "Located in the fertile Maradi region by the Goulbi n'Maradi", "Significant venue for traditional wrestling matches", "Estimated population of around 50,000 residents"],
      es: ["Asentamiento compacto cerca de la metrópoli de Maradi.", "Sede histórica de un importante reino hausa.", "La economía se basa fuertemente en el sorgo, el mijo y el cacahuete.", "Estrechamente vinculada familiar y económicamente con Nigeria.", "Las ceremonias reales preservan el patrimonio histórico.", "Entorno comercial dinámico para productos agrícolas."],
      pt: ["Assentamento compacto perto da metrópole de Maradi.", "Sede histórica de um importante reino Hausa.", "Economia baseada fortemente no sorgo, milheto e amendoim.", "Estreitamente ligada familiar e economicamente com a Nigéria.", "As cerimónias reais preservam o património histórico.", "Ambiente comercial dinâmico para produtos agrícolas."],
      fr: ["Colonie compacte proche de la métropole de Maradi.", "Siège historique d'un important royaume Haoussa.", "L'économie repose fortement sur le sorgho, le mil et l'arachide.", "Étroitement liée familialement et économiquement au Nigeria.", "Les cérémonies royales préservent l'héritage historique.", "Environnement commercial dynamique pour les produits agricoles."],
